cat > out/cf-03-working_capital.json << 'EOF'
{
  "Changes in Working Capital": {"FY0": "-2,161", "FY-1": "-1,426"},
  "components": {
    "FY0": {"Inventories": "-1,884", "Accounts receivable, net and other": "-3,249", "Accounts payable": "2,972", "sum": "-2,161"},
    "FY-1": {"Inventories": "1,449", "Accounts receivable, net and other": "-8,348", "Accounts payable": "5,473", "sum": "-1,426"}
  },
  "excluded_lines": ["Other assets", "Accrued expenses and other", "Unearned revenue"],
  "note": "Per rule, only trade receivables, inventories, and trade payables are summed; 'Other assets', 'Accrued expenses and other', and 'Unearned revenue' are excluded even though presented within the same 'Changes in operating assets and liabilities' block."
}
EOF
cat > out/cf-03-capex.json << 'EOF'
{
  "Gross CAPEX": {"FY0": "-82,999", "FY-1": "-52,729"},
  "Proceeds from Disposal": {"FY0": "5,341", "FY-1": "4,596"},
  "Net CAPEX": {"FY0": "-77,658", "FY-1": "-48,133"},
  "components": {
    "Gross CAPEX source line": "Purchases of property and equipment (only CAPEX line; Amazon capitalizes internal-use software within PP&E, no separate intangible-asset purchase line found)",
    "Proceeds from Disposal source line": "Proceeds from property and equipment sales and incentives"
  },
  "cross_check": "Net CAPEX matches Amazon's own disclosed 'Purchases of property and equipment, net of proceeds from sales and incentives' figures used in its Free Cash Flow note: -48,133 (FY-1) and -77,658 (FY0), confirming the allocation."
}
EOF
cat > out/cf-03-interest_and_taxes.json << 'EOF'
{
  "Cash Interest Paid": {"FY0": "-2,364", "FY-1": "-3,112"},
  "Interest Paid CF Location": "not_in_cf",
  "Cash Taxes Paid": {"FY0": "-12,308", "FY-1": "-11,179"},
  "Taxes Paid CF Location": "not_in_cf",
  "reasoning": {
    "interest": "Sourced from Supplemental Cash Flow Information note (printed page 41): 'Cash paid for interest on debt, net of capitalized interest' ($1,858 FY0 / $2,608 FY-1) + 'Cash paid for interest on finance leases' ($287 FY0 / $308 FY-1) + 'Cash paid for interest on financing obligations' ($219 FY0 / $196 FY-1) = $2,364 FY0 / $3,112 FY-1, reported as negative (outflow). 'Cash paid for operating leases' ($12,341/$10,453) excluded as it represents lease payments, not interest. Capitalized interest is already excluded per the note's own label. Not on the face of the CFS in any section, hence not_in_cf.",
    "taxes": "Sourced from same Supplemental Cash Flow Information note: 'Cash paid for income taxes, net of refunds' = $12,308 FY0 / $11,179 FY-1, reported net of refunds as disclosed, reported as negative (outflow). Not a separate line on the face of the CFS, hence not_in_cf."
  }
}
EOF
cat > out/cf-03-ocf.json << 'EOF'
{
  "Operating Cash Flow (OCF)": {"FY0": "115,877", "FY-1": "84,946"},
  "reasoning": "Accounting standard: US GAAP, indirect method. Extracted line: 'Net cash provided by (used in) operating activities' - the final total at the bottom of the Operating Activities section, after all adjustments, working-capital changes are already the terminal subtotal (no interest/tax deductions shown within the operating section itself, so nothing further was bypassed). No continuing/discontinued split presented; single combined operating total used."
}
EOF
cat > out/cf-03-equity_and_ma.json << 'EOF'
{
  "Capital Increase": {"FY0": "0", "FY-1": "0"},
  "Shareholder Distributions": {"FY0": "0", "FY-1": "0"},
  "Acquisitions and Disposals": {"FY0": "-7,082", "FY-1": "-5,839"},
  "reasoning": {
    "capital_increase": "No equity issuance line appears in the Financing Activities section for FY0 or FY-1; reported as 0 per rule.",
    "shareholder_distributions": "'Common stock repurchased' is '—' (zero) for both FY0 and FY-1 (only FY-2/2022 shows -6,000). No dividend lines present (Amazon pays no dividends in these periods). Reported as 0.",
    "acquisitions_and_disposals": "'Acquisitions, net of cash acquired, non-marketable investments, and other' = -7,082 (FY0) / -5,839 (FY-1), from Investing Activities. This single aggregated line combines business acquisitions with non-marketable (strategic) investment purchases, both in scope per the rule; no separate disposal-of-business proceeds line exists so the net figure as printed is used directly."
  }
}
EOF
cat > out/cf-03-debt_cf.json << 'EOF'
{
  "Debt Related Cash Flows": {"FY0": "-11,812", "FY-1": "-15,879"},
  "components": {
    "FY0": {"Proceeds from short-term debt, and other": "5,142", "Repayments of short-term debt, and other": "-5,060", "Proceeds from long-term debt": "0", "Repayments of long-term debt": "-9,182", "Principal repayments of finance leases": "-2,043", "Principal repayments of financing obligations": "-669", "sum": "-11,812"},
    "FY-1": {"Proceeds from short-term debt, and other": "18,129", "Repayments of short-term debt, and other": "-25,677", "Proceeds from long-term debt": "0", "Repayments of long-term debt": "-3,676", "Principal repayments of finance leases": "-4,384", "Principal repayments of financing obligations": "-271", "sum": "-15,879"}
  },
  "ambiguous_items_excluded": [],
  "note": "All six financing-section debt-type lines included; sum equals the full 'Net cash provided by (used in) financing activities' total for both FY0 and FY-1 because Common stock repurchased is zero in both periods and no other financing lines (equity issuance, dividends, related-party flows) are present."
}
EOF
cat > out/cf-03-non_core.json << 'EOF'
{
  "Other Non-Core Cash Flows": {"FY0": "-10,903", "FY-1": "4,542"},
  "components": {
    "FY0": {"Sales and maturities of marketable securities": "16,403", "Purchases of marketable securities": "-26,005", "Foreign currency effect on cash, cash equivalents, and restricted cash": "-1,301", "sum": "-10,903"},
    "FY-1": {"Sales and maturities of marketable securities": "5,627", "Purchases of marketable securities": "-1,488", "Foreign currency effect on cash, cash equivalents, and restricted cash": "403", "sum": "4,542"}
  },
  "reasoning": "Investing-section residual: 'Sales and maturities of marketable securities' and 'Purchases of marketable securities' are treasury/cash-management flows (marketable securities), explicitly excluded from CAPEX and from Acquisitions & Disposals (not strategic equity investments), so they land in Other Non-Core Cash Flows. No financing-section residual (all financing lines fully allocated to Capital Increase/Shareholder Distributions/Debt CF, each already 0/0/full). 'Foreign currency effect on cash, cash equivalents, and restricted cash' is the separate reconciling FX line, included per rule point 3."
}
EOF
